import std.collection.HashMap
import std.time.DateTime
import std.time.format.*
import std.convert.*

class AccessGatewayFilter {
    public init() {}

    public func filter(request: HashMap<String, Any>): Bool {
        let request_uri = request.get("path").getOrThrow() as String
        let method = request.get("method").getOrThrow() as String

        if (is_start_with(request_uri)) {
            return true
        }
        match (get_jwt_user(request)) {
            case Some(token) =>
                let user = token.get("user").getOrThrow() as HashMap<String, Any>
                let level = user.get("level").getOrThrow() as Int64
                if (level > 2) {
                    set_current_user_info_and_log(user)
                    return true
                } else {
                    return false
                }
            case None => return false
        }
    }

    public func is_start_with(request_uri: String): Bool {
        let start_with = ["/api", "/login"]
        for (s in start_with) {
            if (request_uri.startsWith(s)) {
                return true
            }
        }
        return false
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers = request.get("headers").getOrThrow() as HashMap<String, Any>
        let token = headers.get("Authorization").getOrThrow() as HashMap<String, Any>
        let user = token.get("user").getOrThrow() as HashMap<String, Any>
        let jwt = token.get("jwt").getOrThrow() as String
        let name = user.get("name").getOrThrow() as String

        if (jwt.startsWith(name)) {
            let jwt_str_date = jwt.substring(name.size)
            let jwt_date = DateTime.parse(jwt_str_date, "yyyy-MM-dd")
            let today = DateTime.now()
            let diff = today.sub(jwt_date)
            if (diff.days >= 3) {
                return None
            }
        }
        return Some(token)
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        let host = user.get("address").getOrThrow() as String
        let name = user.get("name").getOrThrow() as String
        let now = DateTime.now().format("yyyy-MM-dd HH:mm:ss")
        println(name + host + now)
    }
}

