import std.collection.ArrayList

class ArrangementCalculator {
    let datas: ArrayList<Int64>

    public init(datas: ArrayList<Int64>) {
        this.datas = datas
    }

    public static func factorial(n: Int64): Int64 {
        if (n <=  1) {
            return 1
        }
        var result = 1
        for (i in 2..n+1) {
            result *= i
        }
        return result
    }

    public static func count(n: Int64, m: Option<Int64>): Int64 {
        let k = m.match(
            Some(v) => v,
            None()  => n
        )
        if (n < 0 || k < 0 || k > n) {
            return 0
        }
        return factorial(n) / factorial(n - k)
    }

    public static func count_all(n: Int64): Int64 {
        if (n < 0) {
            return 0
        }
        var total = 0
        for (i in 1..n+1) {
            total += count(n, Some(i))
        }
        return total
    }

    private func select_permutations(
        prefix: ArrayList<Int64>,
        remaining: ArrayList<Int64>,
        m: Int64,
        result: ArrayList<ArrayList<Int64>>
    ): Unit {
        if (prefix.size == m) {
            result.add(ArrayList<Int64>(prefix))
            return
        }
        for (i in 0..remaining.size) {
            let newPrefix = ArrayList<Int64>(prefix)
            newPrefix.add(remaining[i])
            let newRemaining = ArrayList<Int64>(remaining)
            newRemaining.remove(at: i)
            select_permutations(newPrefix, newRemaining, m, result)
        }
    }

    public func select(m: Option<Int64>): ArrayList<ArrayList<Int64>> {
        let k = m.match(
            Some(v) => v,
            None()  => datas.size
        )
        let result = ArrayList<ArrayList<Int64>>()
        if (k <= 0 || k > datas.size) {
            return result
        }
        select_permutations(
            ArrayList<Int64>(),
            ArrayList<Int64>(datas),
            k,
            result
        )
        return result
    }

    public func select_all(): ArrayList<ArrayList<Int64>> {
        let result = ArrayList<ArrayList<Int64>>()
        for (i in 1..datas.size+1) {
            result.extend(select(Some(i)))
        }
        return result
    }
}

