            return None
        }
        var sum = 0
        var count = 0
        for ((_, v) in student.cources) {
            sum += v
            count += 1
        }
        Some(Float64(sum) / Float64(count))
    }

    public func get_all_students_with_fail_course(): ArrayList<String> {
        var res = ArrayList<String>()
        for ((k, v) in this.students) {
            for ((_, score) in v.cources) {
                if (score < 60) {
                    res.append(k)
                    break
                }
            }
        }
        res
    }

    public func get_course_average(course: String): Option<Float64> {
        var total = 0
        var count = 0
        for ((_, student) in this.students) {
            if (student.cources.contains(course)) {
                let score = student.cources[course]
                if (score >= 0) {
                    total += score
                    count += 1
                }
            }
        }
        if (count > 0) {
            Some(Float64(total) / Float64(count))
        } else {
            None
        }
    }

    public func get_top_student(): Option<String> {
