import std.collection.ArrayList
import std.regex.*

class BalancedBrackets {

    let stack: ArrayList<String>
    let left_brackets: ArrayList<String>
    let right_brackets: ArrayList<String>
    var expr: String

    public init(expr: String) {
        this.stack = ArrayList<String>()
        this.left_brackets = ArrayList<String>(["(", "{", "["])
        this.right_brackets = ArrayList<String>([")", "}", "]"])
        this.expr = expr
    }

    public func clear_expr(): Unit {
        var cleaned = ""
        for (c in this.expr) {
            let s = String(c)
            if (this.left_brackets.contains(s) || this.right_brackets.contains(s)) {
                cleaned = cleaned + s
            }
        }
        this.expr = cleaned
    }

    public func check_balanced_brackets(): Bool {
        this.clear_expr()
        this.stack.clear()
        for (c in this.expr) {
            let s = String(c)
            if (this.left_brackets.contains(s)) {
                this.stack.add(s)
            } else {
                if (this.stack.size() == 0) {
                    return false
                }
                let top = this.stack.removeLast()
                if ((top == "(" && s != ")") ||
                    (top == "{" && s != "}") ||
                    (top == "[" && s != "]")) {
                    return false
                }
            }
        }
        return this.stack.size() == 0
    }
}

