class BinaryDataProcessor {
    var binary_string: String

    public init(binary_string: String) {
        this.binary_string = binary_string
        this.clean_non_binary_chars()
    }

    public func clean_non_binary_chars(): Unit {
        var cleaned = ""
        for (c in this.binary_string) {
            if (c == '0' || c == '1') {
                cleaned += c
            }
        }
        this.binary_string = cleaned
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        var zeroes = 0
        var ones = 0
        for (c in this.binary_string) {
            if (c == '0') {
                zeroes += 1
            } else {
                ones += 1
            }
        }
        let total = this.binary_string.size
        let result = HashMap<String, Float64>()
        result["Zeroes"] = Float64(zeroes) / Float64(total)
        result["Ones"] = Float64(ones) / Float64(total)
        result["Bit length"] = Float64(total)
        return result
    }

    public func convert_to_ascii(): String {
        var bytes = ArrayList<Byte>()
        let len = this.binary_string.size
        for (i in 0..len:8) {
            let byteStr = this.binary_string[i..i+8]
            let decimal = Int32.parse(byteStr, 2)
            bytes.append(decimal.toByte())
        }
        return String.fromUtf8(bytes)
    }

    public func convert_to_utf8(): String {
        var bytes = ArrayList<Byte>()
        let len = this.binary_string.size
        for (i in 0..len:8) {
            let byteStr = this.binary_string[i..i+8]
            let decimal = Int32.parse(byteStr, 2)
            bytes.append(decimal.toByte())
        }
        return String.fromUtf8(bytes)
    }
}

