import std.collection.ArrayList

class BoyerMooreSearch {
    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        var i = patLen - 1
        while (i >= 0) {
            if (pattern[i] == char[0]) {
                return i
            }
            i--
        }
        return -1
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        var i = patLen - 1
        while (i >= 0) {
            if (pattern[i] != text[currentPos + i]) {
                return currentPos + i
            }
            i--
        }
        return -1
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        let positions = ArrayList<Int64>()
        var i = 0
        while (i <= textLen - patLen) {
            let mismatch_index = mismatch_in_text(i)
            if (mismatch_index == -1) {
                positions.append(i)
                i += 1
            } else {
                let match_index = match_in_pattern(text[mismatch_index])
                let shift = mismatch_index - match_index
                if (shift > 0) {
                    i += shift
                } else {
                    i += 1
                }
            }
        }
        return positions
    }
}

