import std.collection.HashMap
import std.collection.ArrayList
import std.convert.Parsable

class Calculator {
    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        let operand_stack = ArrayList<Float64>()
        let operator_stack = ArrayList<String>()
        var num_buffer = ""
        for (c in expression) {
            let ch = String(c)
            if (c >= '0' && c <= '9') || ch == "." {
                num_buffer = num_buffer + ch
            } else {
                if (num_buffer.size > 0) {
                    let v = Float64.parse(num_buffer)
                    if (v is Some<Float64>) {
                        operand_stack.append((v as Some<Float64>).value)
                    }
                    num_buffer = ""
                }
                if (operators.contains(ch)) {
                    while (operator_stack.size > 0 && operator_stack[operator_stack.size - 1] != "(" &&
                           precedence(operator_stack[operator_stack.size - 1]) >= precedence(ch)) {
                        let (os, opS) = apply_operator(operand_stack, operator_stack)
                        operand_stack.clear()
                        operand_stack.extend(os)
                        operator_stack.clear()
                        operator_stack.extend(opS)
                    }
                    operator_stack.append(ch)
                } else if (ch == "(") {
                    operator_stack.append(ch)
                } else if (ch == ")") {
                    while (operator_stack.size > 0 && operator_stack[operator_stack.size - 1] != "(") {
                        let (os, opS) = apply_operator(operand_stack, operator_stack)
                        operand_stack.clear()
                        operand_stack.extend(os)
                        operator_stack.clear()
                        operator_stack.extend(opS)
                    }
                    if (operator_stack.size > 0 && operator_stack[operator_stack.size - 1] == "(") {
                        operator_stack.removeAt(operator_stack.size - 1)
                    }
                }
            }
        }
        if (num_buffer.size > 0) {
            let v = Float64.parse(num_buffer)
            if (v is Some<Float64>) {
                operand_stack.append((v as Some<Float64>).value)
            }
        }
        while (operator_stack.size > 0) {
            let (os, opS) = apply_operator(operand_stack, operator_stack)
            operand_stack.clear()
            operand_stack.extend(os)
            operator_stack.clear()
            operator_stack.extend(opS)
        }
        if (operand_stack.size > 0) {
            Some(operand_stack[operand_stack.size - 1])
        } else {
            None
        }
    }

    public func precedence(op: String): Int64 {
        if (op == "+" || op == "-") { 1 }
        else if (op == "*" || op == "/") { 2 }
        else if (op == "^") { 3 }
        else { 0 }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        let op = operator_stack[operator_stack.size - 1]
        operator_stack.removeAt(operator_stack.size - 1)
        if (operand_stack.size >= 2) {
            let b = operand_stack[operand_stack.size - 1]
            operand_stack.removeAt(operand_stack.size - 1)
            let a = operand_stack[operand_stack.size - 1]
            operand_stack.removeAt(operand_stack.size - 1)
            let fn = operators[op]
            if (fn is Some<(Float64, Float64) -> Float64>) {
                let res = (fn as Some<(Float64, Float64) -> Float64>).value(a, b)
                operand_stack.append(res)
            }
        }
        (operand_stack, operator_stack)
    }
}

