public func add_event(event: Event): Unit {
        this.events.append(event)
    }

    public func remove_event(event: Event): Unit {
        this.events.removeElement(event)
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let result = ArrayList<Event>()
        for (event in this.events) {
            if (event.date.year == date.year && event.date.month == date.month && event.date.day == date.day) {
                result.append(event)
            }
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for (event in this.events) {
            if (start_time < event.end_time && end_time > event.start_time) {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let available_slots = ArrayList<(DateTime, DateTime)>()
        let start_time = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.day, hour: 0, minute: 0)
        let end_time = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.day, hour: 23, minute: 59)

        var current = start_time
        while (current < end_time) {
            let slot_end_time = DateTime.fromUnixTimeStamp(Duration.fromSeconds(current.toUnixTime() + 3600))
            if (this.is_available(current, slot_end_time)) {
                available_slots.append((current, slot_end_time))
            }
            current = DateTime.fromUnixTimeStamp(Duration.fromSeconds(current.toUnixTime() + 3600))
        }
        return available_slots
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let now = DateTime.now()
        let upcoming_events = ArrayList<Event>()
        var count = 0
        for (event in this.events) {
            if (event.start_time >= now) {
                upcoming_events.append(event)
                count += 1
                if (count == num_events) {
                    break
                }
            }
        }
        return upcoming_events
    }

