import std.collection.*

class ChandrasekharSieve {
    let n: Int64
    var primes: ArrayList<Int64> = ArrayList<Int64>()

    public init(n: Int64) {
        this.n = n
        this.primes = generate_primes()
    }

    public func generate_primes(): ArrayList<Int64> {
        if (n < 2) {
            ArrayList<Int64>()
        } else {
            let sieve = Array<Bool>(n + 1, {_ => true})
            sieve[0] = false
            sieve[1] = false

            var p: Int64 = 2
            while (p * p <= n) {
                if (sieve[p]) {
                    var i = p * p
                    while (i <= n) {
                        sieve[i] = false
                        i += p
                    }
                }
                p += 1
            }

            let primes = ArrayList<Int64>()
            for (i in 2..n + 1) {
                if (sieve[i]) {
                    primes.add(i)
                }
            }
            primes
        }
    }

    public func get_primes(): ArrayList<Int64> {
        primes
    }
}

