import std.fs.*
import std.io.*
import std.unicode.*

class CSVProcessor {
    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let content = File.readFrom(file_name)
        let lines = String.fromUtf8(content).split("\n").filter({ s => s.size > 0 })
        var title = ArrayList<String>()
        var data = ArrayList<ArrayList<String>>()

        if (lines.size == 0) {
            return (title, data)
        }

        title = lines[0].split(",").map({ s => s.trim() })
        for (i in 1..lines.size) {
            data.append(lines[i].split(",").map({ s => s.trim() }))
        }
        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        try {
            let file = File.create(file_name)
            for (row in data) {
                let line = row.join(",")
                file.write(line.toArray())
                file.write("\n".toArray())
            }
            file.flush()
            return 1
        } catch (_) {
            return 0
        }
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = read_csv(save_file_name)
        if (data.size == 0) {
            return 0
        }
        var column_data = ArrayList<String>()
        for (row in data) {
            if (N < row.size) {
                column_data.append(row[N].upper())
            }
        }
        var new_data = ArrayList<ArrayList<String>>()
        new_data.append(title)
        new_data.append(column_data)
        let new_file = save_file_name.split(".")[0] + "_process.csv"
        return write_csv(new_data, new_file)
    }
}

