import std.math.round
import std.math.abs
import std.sort.sort

class DataStatistics {
    public func mean(data: ArrayList<Int64>): Float64 {
        var s = 0
        for (v in data) {
            s += v
        }
        return round(Float64(s) / Float64(data.size()), 2)
    }

    public func median(data: ArrayList<Int64>): Float64 {
        let sorted = ArrayList<Int64>(data)
        sort(sorted)
        let n = sorted.size()
        if (n % 2 == 0) {
            let mid = n / 2
            return round((Float64(sorted[mid - 1]) + Float64(sorted[mid])) / 2.0, 2)
        } else {
            return Float64(sorted[n / 2])
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let counter = HashMap<Int64, Int64>()
        for (v in data) {
            counter[v] = counter.getOrDefault(v, 0) + 1
        }
        var maxCount = 0
        for ((_, c) in counter) {
            if (c > maxCount) {
                maxCount = c
            }
        }
        let modes = ArrayList<Int64>()
        for ((v, c) in counter) {
            if (c == maxCount) {
                modes.append(v)
            }
        }
        sort(modes)
        return modes
    }
}
