        var sum = 0.0
        for (v in this.data) {
            sum += v
        }
        return sum
    }

    public func get_min(): Float64 {
        var min = this.data[0]
        for (v in this.data) {
            if (v < min) {
                min = v
            }
        }
        return min
    }

    public func get_max(): Float64 {
        var max = this.data[0]
        for (v in this.data) {
            if (v > max) {
                max = v
            }
        }
        return max
    }

    public func get_variance(): Float64 {
        let n = this.data.size()
        if (n <= 1) {
            return 0.0
        }
        let mean = this.get_sum() / Float64(n)
        var sumSq = 0.0
        for (v in this.data) {
            let diff = v - mean
            sumSq += diff * diff
        }
        return round(sumSq / Float64(n) * 100.0) / 100.0
    }

    public func get_std_deviation(): Float64 {
        let var0 = this.get_variance()
        return round(sqrt(var0) * 100.0) / 100.0
    }

    public func get_correlation(): Float64 {
        1.0
    }
}

