import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs
import std.math.*

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size
        var sum1 = 0.0
        var sum2 = 0.0
        for (i in 0..n) {
            sum1 += data1[i]
            sum2 += data2[i]
        }
        let mean1 = sum1 / Float64(n)
        let mean2 = sum2 / Float64(n)

        var numerator = 0.0
        var sumSq1 = 0.0
        var sumSq2 = 0.0
        for (i in 0..n) {
            let d1 = data1[i] - mean1
            let d2 = data2[i] - mean2
            numerator += d1 * d2
            sumSq1 += d1 * d1
            sumSq2 += d2 * d2
        }
        let denominator = sqrt(sumSq1) * sqrt(sumSq2)
        return if (denominator != 0.0) { numerator / denominator } else { 0.0 }
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size
        var sum = 0.0
        for (x in data) {
            sum += x
        }
        let mean = sum / Float64(n)

        var varSum = 0.0
        for (x in data) {
            varSum += (x - mean) ** 2.0
        }
        let variance = varSum / Float64(n)
        let std_deviation = sqrt(variance)

        if (std_deviation == 0.0) {
            return 0.0
        }

        var skewSum = 0.0
        for (x in data) {
            skewSum += (x - mean) ** 3.0
        }
        let skewness = skewSum * Float64(n) / (Float64(n - 1) * Float64(n - 2) * std_deviation ** 3.0)
        return skewness
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size
        var sum = 0.0
        for (x in data) {
            sum += x
        }
        let mean = sum / Float64(n)

        var varSum = 0.0
        for (x in data) {
            varSum += (x - mean) ** 2.0
        }
        let std_dev = sqrt(varSum / Float64(n))

        if (std_dev == 0.0) {
            return Float64.nan
        }

        var fourthSum = 0.0
        for (x in data) {
            fourthSum += (x - mean) ** 4.0
        }
        let fourth_moment = fourthSum / Float64(n)
        let kurtosis_value = (fourth_moment / (std_dev ** 4.0)) - 3.0
        return kurtosis_value
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let coeff = 1.0 / (sigma * sqrt(2.0 * Float64.pi))
        let result = ArrayList<Float64>()
        for (x in data) {
            let exponent = -0.5 * ((x - mu) / sigma) ** 2.0
            result.add(coeff * exp(exponent))
        }
        return result
    }
}

