        let skewness = skewSum * Float64(n) / (Float64(n - 1) * Float64(n - 2) * std_deviation ** 3.0)
        return skewness
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size
        var sum = 0.0
        for (x in data) {
            sum += x
        }
        let mean = sum / Float64(n)

        var varSum = 0.0
        for (x in data) {
            varSum += (x - mean) ** 2.0
        }
        let std_dev = sqrt(varSum / Float64(n))

        if (std_dev == 0.0) {
            return Float64.nan
        }

        var fourthSum = 0.0
        for (x in data) {
            fourthSum += (x - mean) ** 4.0
        }
        let fourth_moment = fourthSum / Float64(n)
        let kurtosis_value = (fourth_moment / (std_dev ** 4.0)) - 3.0
        return kurtosis_value
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let coeff = 1.0 / (sigma * sqrt(2.0 * Float64.pi))
        let result = ArrayList<Float64>()
        for (x in data) {
            let exponent = -0.5 * ((x - mu) / sigma) ** 2.0
            result.add(coeff * exp(exponent))
        }
        return result
    }
}
