                let base = 'A'.codePointAt(0)
                let shifted = ((c.codePointAt(0) - base - shift + 26) % 26 + base).toChar()
                plaintext.append(shifted)
            } else if (c >= 'a' && c <= 'z') {
                let base = 'a'.codePointAt(0)
                let shifted = ((c.codePointAt(0) - base - shift + 26) % 26 + base).toChar()
                plaintext.append(shifted)
            } else {
                plaintext.append(c)
            }
        }
        return plaintext.toString()
    }

    public func vigenere_decipher(ciphertext: String): String {
        let decrypted = StringBuilder()
        var keyIndex = 0
        for (c in ciphertext) {
            if (c >= 'A' && c <= 'Z') {
                let keyChar = this.key[keyIndex % this.key.size].lowercase()
                let shift = keyChar.codePointAt(0) - 'a'.codePointAt(0)
                let base = 'A'.codePointAt(0)
                let shifted = ((c.codePointAt(0) - base - shift + 26) % 26 + base).toChar()
                decrypted.append(shifted)
                keyIndex++
            } else if (c >= 'a' && c <= 'z') {
                let keyChar = this.key[keyIndex % this.key.size].lowercase()
                let shift = keyChar.codePointAt(0) - 'a'.codePointAt(0)
                let base = 'a'.codePointAt(0)
                let shifted = ((c.codePointAt(0) - base - shift + 26) % 26 + base).toChar()
                decrypted.append(shifted)
                keyIndex++
            } else {
