                dir = -dir
            }
            fence[row][i] = '\0'
            row += dir
        }
        var index = 0
        for (i in 0..rails) {
            for (j in 0..len) {
                if (fence[i][j] == '\0') {
                    fence[i][j] = encrypted_text[index]
