import std.collection.ArrayList

class EncryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        var ciphertext = ""
        for (c in plaintext) {
            if (c >= 'A' && c <= 'Z') {
                ciphertext += Char((UInt64(c) - UInt64('A') + UInt64(shift)) % 26 + UInt64('A'))
            } else if (c >= 'a' && c <= 'z') {
                ciphertext += Char((UInt64(c) - UInt64('a') + UInt64(shift)) % 26 + UInt64('a'))
            } else {
                ciphertext += c
            }
        }
        return ciphertext
    }

    public func vigenere_cipher(plain_text: String): String {
        var encrypted_text = ""
        var key_index = 0
        let key_len = key.size
        for (c in plain_text) {
            if (c >= 'A' && c <= 'Z') {
                let shift = UInt64(key[key_index % key_len].lowercaseChar()) - UInt64('a')
                encrypted_text += Char((UInt64(c) - UInt64('A') + shift) % 26 + UInt64('A'))
                key_index++
            } else if (c >= 'a' && c <= 'z') {
                let shift = UInt64(key[key_index % key_len].lowercaseChar()) - UInt64('a')
                encrypted_text += Char((UInt64(c) - UInt64('a') + shift) % 26 + UInt64('a'))
                key_index++
            } else {
                encrypted_text += c
            }
        }
        return encrypted_text
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        let n = plain_text.size
        var fence = ArrayList<ArrayList<Char>>()
        for (i in 0..rails) {
            fence.append(ArrayList<Char>())
            for (j in 0..n) {
                fence[i].append('\n')
            }
        }
        var direction = -1
        var row = 0
        var col = 0
        for (c in plain_text) {
            if (row == 0 || row == rails - 1) {
                direction = -direction
            }
            fence[row][col] = c
            col += 1
            row += direction
        }
        var encrypted_text = ""
        for (i in 0..rails) {
            for (j in 0..n) {
                if (fence[i][j] != '\n') {
                    encrypted_text += fence[i][j]
                }
            }
        }
        return encrypted_text
    }
}

