import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {
    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        prepare(transform(expression))
        let result_stack = ArrayList<Decimal>()
        let n = postfix_stack.size()
        for (i in 0..n) {
            let current = postfix_stack[n-1-i]
            if (!is_operator(current)) {
                let v = Decimal(current.replace("~", "-"))
                result_stack.append(v)
            } else {
                let b = result_stack.pop()
                let a = result_stack.pop()
                let r = _calculate(a, b, current)
                result_stack.append(r)
            }
        }
        return result_stack[0].toFloat64()
    }

    public func prepare(expression: String): Unit {
        let op_stack = ArrayList<String>()
        op_stack.append(",")
        let chars = expression.toArray()
        var i = 0
        var count = 0
        let n = chars.size()
        while (i < n) {
            let c = chars[i]
            if (is_operator(c)) {
                if (count > 0) {
                    postfix_stack.append(String(chars[(i-count)..i]))
                }
                let peek = op_stack[op_stack.size()-1]
                if (c == ")") {
                    while (op_stack[op_stack.size()-1] != "(") {
                        postfix_stack.append(op_stack.pop())
                    }
                    op_stack.pop()
                } else {
                    while (c != "(" && peek != "," && compare(c, peek)) {
                        postfix_stack.append(op_stack.pop())
                        peek = op_stack[op_stack.size()-1]
                    }
                    op_stack.append(c)
                }
                count = 0
            } else {
                count += 1
            }
            i += 1
        }
        if (count > 0) {
            postfix_stack.append(String(chars[(i-count)..i]))
        }
        while (op_stack[op_stack.size()-1] != ",") {
            postfix_stack.append(op_stack.pop())
        }
    }

    public static func is_operator(c: String): Bool {
        return c == "+" || c == "-" || c == "*" || c == "/" || c == "(" || c == ")" || c == "%"
    }

    public func compare(cur: String, peek: String): Bool {
        var a = cur
        var b = peek
        if (a == "%") { a = "/" }
        if (b == "%") { b = "/" }
        return operat_priority[(b[0].code - 40)] >= operat_priority[(a[0].code - 40)]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
            case "-" => first_value - second_value
            case "*" => first_value * second_value
            case "/" => first_value / second_value
            case "%" => first_value % second_value
            case _ => Decimal(0)
        }
    }

    public static func transform(expression: String): String {
        var s = expression.replace(Regex("\\s+"), "")
        s = s.replace(Regex("=$"), "")
        let chars = s.toArray()
        var i = 0
        while (i < chars.size()) {
            if (chars[i] == "-") {
                if (i == 0) {
                    chars[i] = "~"
                } else {
                    let prev = chars[i-1]
                    if (prev == "+" || prev == "-" || prev == "*" || prev == "/" || prev == "(" || prev == "E" || prev == "e") {
                        chars[i] = "~"
                    }
                }
            }
            i += 1
        }
        var res = String(chars)
        if (chars[0] == "~" && chars.size() > 1 && chars[1] == "(") {
            res = "0" + res
        }
        res
    }
}

