import std.collection.HashMap

class Hotel {

    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        let ava = available_rooms[room_type]
        if (ava == 0) {
            return "false"
        }
        if (room_number <= ava) {
            if (booked_rooms[room_type] == 0) {
                booked_rooms[room_type] = HashMap<String, Int64>()
            }
            let cur = booked_rooms[room_type][name]
            booked_rooms[room_type][name] = cur + room_number
            available_rooms[room_type] = ava - room_number
            return "Success!"
        } else {
            return "${ava}"
        }
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        let bookMap = booked_rooms[room_type]
        if (bookMap == 0) {
            return false
        }
        let booked = bookMap[name]
        if (booked == 0) {
            return false
        }
        if (room_number > booked) {
            return false
        }
        if (room_number == booked) {
            bookMap.remove(name)
        } else {
            bookMap[name] = booked - room_number
        }
        return true
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        let ava = available_rooms[room_type]
        if (ava == 0) {
            available_rooms[room_type] = room_number
        } else {
            available_rooms[room_type] = ava + room_number
        }
    }

    public func get_available_rooms(room_type: String): Int64 {
        return available_rooms[room_type]
    }
}

