import std.convert.*
import std.collection.*

class IPAddress {

    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let parts = ip_address.split(".")
        if (parts.size() != 4) {
            return false
        }
        for (p in parts) {
            match (UInt16.tryParse(p)) {
                case Some(n) =>
                    if (n > 255) {
                        return false
                    }
                case None => return false
            }
        }
        return true
    }

    public func get_octets(): ArrayList<String> {
        if (!is_valid()) {
            return ArrayList<String>()
        }
        return ArrayList(ip_address.split("."))
    }

    public func get_binary(): String {
        if (!is_valid()) {
            return ""
        }
        let octets = ip_address.split(".")
        let binParts = ArrayList<String>()
        for (o in octets) {
            let n = UInt16.parse(o)
            binParts.append(n.format("08b"))
        }
        return binParts.join(".")
    }
}

