import std.collection.ArrayList
import std.math.*

class KappaCalculator {
    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var P0: Float64 = 0.0
        var sum: Float64 = 0.0
        let xsum = ArrayList<Float64>()
        let ysum = ArrayList<Float64>()

        for (i in 0..k) {
            xsum.add(0.0)
            ysum.add(0.0)
        }

        for (i in 0..k) {
            for (j in 0..k) {
                let v = Float64(testData[i][j])
                sum += v
                xsum[i] += v
                ysum[j] += v
                if (i == j) {
                    P0 += v
                }
            }
        }

        P0 = P0 / sum
        var Pe: Float64 = 0.0
        for (i in 0..k) {
            Pe += (xsum[i] * ysum[i])
        }
        Pe = Pe / (sum * sum)

        return (P0 - Pe) / (1.0 - Pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var sum: Float64 = 0.0
        var P0: Float64 = 0.0

        for (i in 0..N) {
            var rowSum: Float64 = 0.0
            var temp: Float64 = 0.0
            for (j in 0..k) {
                let v = Float64(testData[i][j])
                rowSum += v
                temp += v * v
            }
            sum += rowSum
            temp -= Float64(n)
            temp /= Float64((n - 1) * n)
            P0 += temp
        }
        P0 = P0 / Float64(N)

        var ysum = ArrayList<Float64>()
        for (j in 0..k) {
            var colSum: Float64 = 0.0
            for (i in 0..N) {
                colSum += Float64(testData[i][j])
            }
            ysum.add((colSum / sum) * (colSum / sum))
        }

        var Pe: Float64 = 0.0
        for (j in 0..k) {
            Pe += ysum[j]
        }

        return (P0 - Pe) / (1.0 - Pe)
    }
}

