import std.collection.ArrayList
import std.regex.Regex

class LongestWord {

    let word_list: ArrayList<String>

    public init() {
        this.word_list = ArrayList<String>()
    }

    public func add_word(word: String): Unit {
        this.word_list.append(word)
    }

    public func find_longest_word(sentence: String): String {
        let punctRegex = Regex("\\p{P}")
        let cleaned = punctRegex.replace(sentence, "")

        var longest_word = ""
        let parts = cleaned.split(" ")

        for (word in parts) {
            for (dictWord in this.word_list) {
                if (word == dictWord && word.size > longest_word.size) {
                    longest_word = word
                }
            }
        }

        return longest_word
    }
}

