                if (totalNum == 0 || subList.size() == 0) {
                    return (0.0, ArrayList<Float64>([0.0]))
                }
                var mr: Float64 = 0.0
                for (i in 0..subList.size()) {
                    if (subList[i] == 1) {
                        mr = 1.0 / Float64(i + 1)
                        break
                    }
                }
                return (mr, ArrayList<Float64>([mr]))

            case (list: ArrayList<(ArrayList<Int64>, Int64)>) =>
                let separateResult = ArrayList<Float64>()
                for (item in list) {
                    let (subList, totalNum) = item
                    if (totalNum == 0 || subList.size() == 0) {
                        separateResult.append(0.0)
                        continue
