import std.random.Random
import std.collection.ArrayList

class MusicPlayer {
    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        this.playlist = ArrayList<String>()
        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        let index = this.playlist.indexOf(song)
        if (index >= 0) {
            this.playlist.remove(at: index)
            if (this.current_song == Some(song)) {
                this.stop()
            }
        }
    }

    public func play(): Option<String> {
        if (this.playlist.size == 0) {
            return None
        }
        if (this.current_song == None) {
            this.current_song = Some(this.playlist[0])
        }
        this.current_song
    }

    public func stop(): Bool {
        if (this.current_song != None) {
            this.current_song = None
            true
        } else {
            false
        }
    }

    public func switch_song(): Bool {
        match (this.current_song) {
            case Some(song) =>
                let current_index = this.playlist.indexOf(song)
                if (current_index >= 0 && current_index < this.playlist.size - 1) {
                    this.current_song = Some(this.playlist[current_index + 1])
                    true
                } else {
                    false
                }
            case None => false
        }
    }

    public func previous_song(): Bool {
        match (this.current_song) {
            case Some(song) =>
                let current_index = this.playlist.indexOf(song)
                if (current_index > 0) {
                    this.current_song = Some(this.playlist[current_index - 1])
                    true
                } else {
                    false
                }
            case None => false
        }
    }

    public func set_volume(volume: Int64): Bool {
        if (0 <= volume && volume <= 100) {
            this.volume = volume
            true
        } else {
            false
        }
    }

    public func shuffle(): Bool {
        if (this.playlist.size == 0) {
            return false
        }
        let rng = Random()
        for (i in this.playlist.size - 1..0) {
            let j = (rng.nextBits(31) % (i + 1)).toInt64()
            let temp = this.playlist[i]
            this.playlist[i] = this.playlist[j]
            this.playlist[j] = temp
        }
        true
    }
}

