import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {
    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let wordsList = ArrayList<ArrayList<String>>()
        for (str in string_list) {
            let onlyEngSpace = Regex("[^a-zA-Z\\s]").replaceAll(str, "")
            let lowerStr = onlyEngSpace.toLowerCase()
            let words = ArrayList<String>()
            for (word in lowerStr.split(" ")) {
                if (word.size() > 0) {
                    words.append(word)
                }
            }
            wordsList.append(words)
        }
        return wordsList
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        let freq = HashMap<String, Int64>()
        for (words in words_list) {
            for (word in words) {
                let cnt = freq.getOrDefault(word, 0)
                freq[word] = cnt + 1
            }
        }
        let entries = ArrayList<(String, Int64)>()
        for ((k, v) in freq) {
            entries.append((k, v))
        }
        sort(entries, (a, b) => b.1 - a.1)
        let top5 = HashMap<String, Int64>()
        for (i in 0..5) {
            if (i >= entries.size()) { break }
            let (k, v) = entries[i]
            top5[k] = v
        }
        return top5
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let wordsList = process_data(string_list)
        return calculate_word_frequency(wordsList)
    }
}

