import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        let out = ArrayList<Rune>()
        var pos = 0
        let runes = string.toRunes()
        let length = runes.size()

        while (pos < length - 2) {
            if (runes[pos] == r'&' && runes[pos + 1] == r'#') {
                var start = pos + 2
                var isHex = false
                let firstChar = runes[start]

                if (firstChar == r'x' || firstChar == r'X') {
                    start += 1
                    isHex = true
                }

                if (start == length) {
                    break
                }

                var end = start
                while (end < length && is_hex_char(runes[end])) {
                    end += 1
                }

                if (end < length && runes[end] == r';') {
                    let entityStr = String(runes[start..end])
                    let radix = if (isHex) 16 else 10
                    match (Int32.tryParse(entityStr, radix: radix)) {
                        case Some(value) =>
                            out.put(Rune(value))
                            pos = end + 1
                            continue
                        case None => out.put(runes[pos])
                    }
                } else {
                    out.put(runes[pos])
                }
            } else {
                out.put(runes[pos])
            }
            pos += 1
        }

        while (pos < length) {
            out.put(runes[pos])
            pos += 1
        }

        return String(out)
    }

    public static func is_hex_char(char: Rune): Bool {
        (char >= r'0' && char <= r'9') ||
        (char >= r'a' && char <= r'f') ||
        (char >= r'A' && char <= r'F')
    }
}

