                    out.put(runes[pos])
                }
            } else {
                out.put(runes[pos])
            }
            pos += 1
        }

        while (pos < length) {
            out.put(runes[pos])
            pos += 1
        }

        return String(out)
    }

    public static func is_hex_char(char: Rune): Bool {
        (char >= r'0' && char <= r'9') ||
        (char >= r'a' && char <= r'f') ||
        (char >= r'A' && char <= r'F')
    }
