import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let n = data.size()
        if (n == 0) {
            return 0.0
        }
        var sorted = ArrayList<Int64>()
        for (v in data) {
            sorted.append(v)
        }
        sort<Int64>(sorted)
        if (n % 2 == 1) {
            return Float64(sorted[n / 2])
        } else {
            return (Float64(sorted[n / 2 - 1]) + Float64(sorted[n / 2])) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let counts = HashMap<Int64, Int64>()
        for (v in data) {
            counts[v] = counts.getOrDefault(v, 0) + 1
        }
        var maxCount: Int64 = 0
        for ((_, c) in counts) {
            if (c > maxCount) {
                maxCount = c
            }
        }
        let modes = ArrayList<Int64>()
        for ((v, c) in counts) {
            if (c == maxCount) {
                modes.append(v)
            }
        }
        return modes
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        let n = x.size()
        if (n != y.size() || n == 0) {
            return None
        }
        var sumX: Float64 = 0.0
        var sumY: Float64 = 0.0
        for (i in 0..n) {
            sumX += Float64(x[i])
            sumY += Float64(y[i])
        }
        let meanX = sumX / Float64(n)
        let meanY = sumY / Float64(n)
        var num: Float64 = 0.0
        var denX: Float64 = 0.0
        var denY: Float64 = 0.0
        for (i in 0..n) {
            let dx = Float64(x[i]) - meanX
            let dy = Float64(y[i]) - meanY
            num += dx * dy
            denX += dx * dx
            denY += dy * dy
        }
        let den = sqrt(denX * denY)
        if (den == 0.0) {
            return None
        }
        return Some(num / den)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        let n = data.size()
        if (n == 0) {
            return None
        }
        var sum: Float64 = 0.0
        for (v in data) {
            sum += Float64(v)
        }
        return Some(sum / Float64(n))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let rows = data.size()
        if (rows == 0) {
            return ArrayList<ArrayList<Float64>>()
        }
        let cols = data[0].size()
        var matrix = ArrayList<ArrayList<Float64>>()
        for (i in 0..cols) {
            var row = ArrayList<Float64>()
            for (j in 0..cols) {
                var col1 = ArrayList<Int64>()
                var col2 = ArrayList<Int64>()
                for (k in 0..rows) {
                    col1.append(data[k][i])
                    col2.append(data[k][j])
                }
                let corr = correlation(col1, col2)
                match (corr) {
                    case Some(v) => row.append(v)
                    case None => row.append(0.0)
                }
            }
            matrix.append(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let n = data.size()
        if (n < 2) {
            return None
        }
        let m = mean(data)
        match (m) {
            case None => return None
            case Some(meanValue) =>
                var sum: Float64 = 0.0
                for (v in data) {
                    let diff = Float64(v) - meanValue
                    sum += diff * diff
                }
                let variance = sum / Float64(n - 1)
                return Some(sqrt(variance))
        }
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let m = mean(data)
        let s = standard_deviation(data)
        match (m, s) {
            case (Some(meanValue), Some(stdDev)) =>
                if (stdDev == 0.0) {
                    return None
                }
                var scores = ArrayList<Float64>()
                for (v in data) {
                    scores.append((Float64(v) - meanValue) / stdDev)
                }
                return Some(scores)
            case _ => return None
        }
    }
}

