        if (n < 2) {
            return None
        }
        let m = mean(data)
        match (m) {
            case None => return None
            case Some(meanValue) =>
                var sum: Float64 = 0.0
                for (v in data) {
                    let diff = Float64(v) - meanValue
                    sum += diff * diff
                }
                let variance = sum / Float64(n - 1)
                return Some(sqrt(variance))
        }
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let m = mean(data)
        let s = standard_deviation(data)
        match (m, s) {
            case (Some(meanValue), Some(stdDev)) =>
                if (stdDev == 0.0) {
                    return None
                }
                var scores = ArrayList<Float64>()
                for (v in data) {
                    scores.append((Float64(v) - meanValue) / stdDev)
                }
                return Some(scores)
            case _ => return None
        }
    }
}
