import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {

    let PI = 3.141592653589793

    public init() {}

    public func cos(x: Float64): Float64 {
        let rad = x / 180.0 * PI
        var sum: Float64 = 1.0
        var term: Float64 = 1.0
        for (k in 1..50) {
            term = -term * rad * rad / Float64((2 * k - 1) * (2 * k))
            sum += term
        }
        return round(sum, 10)
    }

    public func factorial(a: Int64): Decimal {
        var res: Decimal = Decimal(1)
        for (i in 2..=a) {
            res *= Decimal(i)
        }
        return res
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        let rad = x / 180.0 * PI
        var sum: Float64 = 1.0
        var term: Float64 = 1.0
        for (k in 1..n) {
            term = -term * rad * rad / Float64((2 * k - 1) * (2 * k))
            sum += term
        }
        return sum
    }

    public func sin(x: Float64): Float64 {
        let rad = x / 180.0 * PI
        var sum: Float64 = 0.0
        var term: Float64 = rad
        var k = 1
        while (abs(term) >= 1e-15) {
            sum += term
            term = -term * rad * rad / Float64((2 * k + 1) * (2 * k))
            k += 1
        }
        return round(sum, 10)
    }

    public func tan(x: Float64): Option<Float64> {
        let c = cos(x)
        if (abs(c - 0.0) <= 0.000001) {
            return None
        }
        return Some(round(sin(x) / c, 10))
    }
}

