class URLHandler {

    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let scheme_end = url.find("://")
        if (scheme_end >= 0) {
            return Some(url[0..scheme_end])
        }
        return None
    }

    public func get_host(): Option<String> {
        let scheme_end = url.find("://")
        if (scheme_end >= 0) {
            let rest = url[scheme_end + 3..]
            let host_end = rest.find("/")
            if (host_end >= 0) {
                return Some(rest[0..host_end])
            } else {
                return Some(rest)
            }
        }
        return None
    }

    public func get_path(): Option<String> {
        let scheme_end = url.find("://")
        if (scheme_end >= 0) {
            let rest = url[scheme_end + 3..]
            let host_end = rest.find("/")
            if (host_end >= 0) {
                return Some(rest[host_end..])
            }
        }
        return None
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let query_start = url.find("?")
        if (query_start >= 0) {
            let fragment_start = url.find("#")
            let query_end = if (fragment_start >= 0) fragment_start else url.size
            let query_string = url[query_start + 1..query_end]
            let params = HashMap<String, String>()
            if (query_string.size > 0) {
                let pairs = query_string.split("&")
                for (pair in pairs) {
                    let kv = pair.split("=")
                    if (kv.size == 2) {
                        params.put(kv[0], kv[1])
                    }
                }
            }
            return Some(params)
        }
        return None
    }

    public func get_fragment(): Option<String> {
        let fragment_start = url.find("#")
        if (fragment_start >= 0) {
            return Some(url[fragment_start + 1..])
        }
        return None
    }
}

