import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let dot = dotProduct(vector_1, vector_2)
        let norm1 = norm(vector_1)
        let norm2 = norm(vector_2)
        if (norm1 == 0.0 || norm2 == 0.0) {
            return 0.0
        }
        return dot / (norm1 * norm2)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        let norm1 = norm(vector_1)
        if (norm1 == 0.0) {
            for (_ in vectors_all) {
                result.append(0.0)
            }
            return result
        }
        for (v in vectors_all) {
            let dot = dotProduct(vector_1, v)
            let normV = norm(v)
            let sim = normV == 0.0 ? 0.0 : dot / (norm1 * normV)
            result.append(sim)
        }
        return result
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if (vector_list_1.size() == 0 || vector_list_2.size() == 0) {
            throw ZeroDivisionError("At least one of the passed list is empty.")
        }
        let mean1 = meanVector(vector_list_1)
        let mean2 = meanVector(vector_list_2)
        return similarity(mean1, mean2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>()
        for ((k, v) in number_dict) {
            let idf = log((Float64(total_num) + 1.0) / (v + 1.0))
            result[k] = idf
        }
        return result
    }

    private static func dotProduct(a: ArrayList<Float64>, b: ArrayList<Float64>): Float64 {
        var sum = 0.0
        let n = a.size()
        for (i in 0..n) {
            sum += a[i] * b[i]
        }
        return sum
    }

    private static func norm(v: ArrayList<Float64>): Float64 {
        var sum = 0.0
        for (x in v) {
            sum += x * x
        }
        return sqrt(sum)
    }

    private static func meanVector(vecs: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let dim = vecs[0].size()
        let mean = ArrayList<Float64>()
        for (_ in 0..dim) {
            mean.append(0.0)
        }
        for (v in vecs) {
            for (i in 0..dim) {
                mean[i] += v[i]
            }
        }
        let n = Float64(vecs.size())
        for (i in 0..dim) {
            mean[i] = mean[i] / n
        }
        return mean
    }
}

